import React, {useEffect, useState} from 'react'
import s2 from '../../s1-main/App.module.css'
import s from './HW15.module.css'
import axios from 'axios'
import SuperPagination from './common/c9-SuperPagination/SuperPagination'
import {useSearchParams} from 'react-router-dom'
import SuperSort from './common/c10-SuperSort/SuperSort'

type TechType = {
    id: number
    tech: string
    developer: string
}

type ParamsType = {
    sort: string
    page: number
    count: number
}

type SearchParamsType = {
    page?: string
    count?: string
    sort?: string
}

const getTechs = (params: ParamsType) => {
    console.log('Sending request with params:', params) // Отладочная информация
    return axios
        .get<{ techs: TechType[], totalCount: number }>(
            'https://samurai.it-incubator.io/api/3.0/homework/test3',
            {params}
        )
        .catch((e) => {
            alert(e.response?.data?.errorText || e.message)
        })
}

const HW15 = () => {
    const [sort, setSort] = useState('')
    const [page, setPage] = useState(1)
    const [count, setCount] = useState(4)
    const [idLoading, setLoading] = useState(false)
    const [totalCount, setTotalCount] = useState(100)
    const [searchParams, setSearchParams] = useSearchParams()
    const [techs, setTechs] = useState<TechType[]>([])

    const sendQuery = (params: ParamsType) => {
        setLoading(true)
        getTechs(params)
            .then((res) => {
                if (res && res.data) {
                    setTechs(res.data.techs)
                    setTotalCount(res.data.totalCount)

                    console.log('Received developers:', res.data.techs.map(t => t.developer))
                    console.log('Sort direction:', params.sort?.startsWith('1') ? 'DESCENDING' : 'ASCENDING')
                }
                setLoading(false)
            })
    }

    const onChangePagination = (newPage: number, newCount: number) => {
        setPage(newPage)
        setCount(newCount)

        const newParams: SearchParamsType = {
            ...Object.fromEntries(searchParams),
            page: newPage.toString(),
            count: newCount.toString()
        }

        if (sort) {
            newParams.sort = sort
        }

        sendQuery({page: newPage, count: newCount, sort})
        setSearchParams(newParams as Record<string, string>)
    }

    const onChangeSort = (newSort: string) => {
        console.log('Sort changed to:', newSort)
        setSort(newSort)
        setPage(1)

        const newParams: SearchParamsType = {
            ...Object.fromEntries(searchParams),
            sort: newSort,
            page: '1'
        }

        sendQuery({page: 1, count, sort: newSort})
        setSearchParams(newParams as Record<string, string>)
    }

    useEffect(() => {
        const params: SearchParamsType = Object.fromEntries(searchParams)
        const pageParam = params.page ? parseInt(params.page) : 1
        const countParam = params.count ? parseInt(params.count) : 4
        const sortParam = params.sort || ''

        setPage(pageParam)
        setCount(countParam)
        setSort(sortParam)

        sendQuery({page: pageParam, count: countParam, sort: sortParam})
    }, [])

    const mappedTechs = techs.map(t => (
        <div key={t.id} className={s.row}>
            <div id={'hw15-tech-' + t.id} className={s.tech}>
                {t.tech}
            </div>

            <div id={'hw15-developer-' + t.id} className={s.developer}>
                {t.developer}
            </div>
        </div>
    ))

    return (
        <div id={'hw15'}>
            <div className={s2.hwTitle}>Homework #15</div>

            <div className={s2.hw}>
                {idLoading && <div id={'hw15-loading'} className={s.loading}>Loading...</div>}

                <SuperPagination
                    page={page}
                    itemsCountForPage={count}
                    totalCount={totalCount}
                    onChange={onChangePagination}
                />

                <div className={s.rowHeader}>
                    <div className={s.techHeader}>
                        tech
                        <SuperSort sort={sort} value={'tech'} onChange={onChangeSort}/>
                    </div>

                    <div className={s.developerHeader}>
                        developer
                        <SuperSort sort={sort} value={'developer'} onChange={onChangeSort}/>
                    </div>
                </div>

                {mappedTechs}
            </div>
        </div>
    )
}

export default HW15