import React from 'react'
import SuperSelect from '../../../hw07/common/c5-SuperSelect/SuperSelect'
import {Pagination} from '@mui/material'
import s from './SuperPagination.module.css'

export type SuperPaginationPropsType = {
    id?: string
    page: number
    itemsCountForPage: number
    totalCount: number
    onChange: (page: number, count: number) => void
}

const SuperPagination: React.FC<SuperPaginationPropsType> = (
    {
        page, itemsCountForPage, totalCount, onChange, id = 'hw15',
    }
) => {
    const lastPage = Math.ceil(totalCount / itemsCountForPage)

    const onChangeCallback = (event: any, page: number) => {
        onChange(page, itemsCountForPage)
    }

    const onChangeSelect = (id: number | string) => {
        // Исправляем: передаем значение, а не event
        onChange(1, Number(id)) // при изменении количества элементов сбрасываем на первую страницу
    }

    return (
        <div className={s.pagination}>
            <Pagination
                id={id + '-pagination'}
                sx={{
                    marginRight: '24px',
                    '& .MuiPaginationItem-root': {
                        color: '#000000',
                        fontSize: '14px',
                        minWidth: '24px',
                        height: '24px',
                    },
                    '& .Mui-selected': {
                        backgroundColor: '#0066CC',
                        color: '#FFFFFF',
                    },
                    '& .MuiPaginationItem-root:hover': {
                        backgroundColor: '#E5F0FF',
                    },
                    '& .Mui-selected:hover': {
                        backgroundColor: '#0059B2',
                    },
                }}
                page={page}
                count={lastPage}
                onChange={onChangeCallback}
                hideNextButton
                hidePrevButton
            />

            <span className={s.text1}>
                показать
            </span>

            <SuperSelect
                id={id + '-pagination-select'}
                value={itemsCountForPage}
                options={[
                    {id: 4, value: 4},
                    {id: 7, value: 7},
                    {id: 10, value: 10},
                ]}
                onChangeOption={onChangeSelect} // Используем onChangeOption вместо onChange
            />

            <span className={s.text2}>
                строк в таблице
            </span>
        </div>
    )
}

export default SuperPagination